INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5570804, 806866, 43774, '<td valign="top">A very pretty setup, good colours.</td>', 'A very pretty setup, good colours.', '2009-07-13 12:44:54.000000', NULL, 1),
(5570805, 806237, 43774, '<td valign="top">Nice DOF, a light summery photo.</td>', 'Nice DOF, a light summery photo.', '2009-07-13 12:45:07.000000', NULL, 1),
(5570807, 805686, 43774, '<td valign="top">A few too many water drops for my tastes. Is the flower in focus? Hard to tell. Nice detail in the orchid.</td>', 'A few too many water drops for my tastes. Is the flower in focus? Hard to tell. Nice detail in the orchid.', '2009-07-13 12:45:47.000000', NULL, 1),
(5570808, 806888, 43774, '<td valign="top">Very pretty, haven''t seen this before.</td>', 'Very pretty, haven''t seen this before.', '2009-07-13 12:45:59.000000', NULL, 1),
(5570809, 806636, 43774, '<td valign="top">Cool looking insect, pretty flowers.</td>', 'Cool looking insect, pretty flowers.', '2009-07-13 12:46:11.000000', NULL, 1),
(5570818, 805874, 43774, '<td valign="top">Nice composition and lighting.</td>', 'Nice composition and lighting.', '2009-07-13 12:47:35.000000', NULL, 1),
(5570838, 806295, 15711, '<td valign="top">Stunning and unexpected. I''ll be curious to read your comments when it''s over. 8</td>', 'Stunning and unexpected. I''ll be curious to read your comments when it''s over. 8', '2009-07-13 13:01:24.000000', NULL, 1),
(5570858, 806833, 69368, '<td valign="top">not sure about the crop, but a very good fokus</td>', 'not sure about the crop, but a very good fokus', '2009-07-13 13:15:14.000000', NULL, 1),
(5570859, 806893, 69368, '<td valign="top">fantastic details here, nice naturally color and a good crop. Good luck!</td>', 'fantastic details here, nice naturally color and a good crop. Good luck!', '2009-07-13 13:16:15.000000', NULL, 1),
(5570865, 806610, 98171, '<td valign="top">I love this photo. If I must say anything negative about it, I think I would prefer it in black and white. I would definitely buy a print of this and hang it on my wall.</td>', 'I love this photo. If I must say anything negative about it, I think I would prefer it in black and white. I would definitely buy a print of this and hang it on my wall.', '2009-07-13 13:20:45.000000', NULL, 1),
(5570866, 806370, 98171, '<td valign="top">very fitting title, I see it =)</td>', 'very fitting title, I see it =)', '2009-07-13 13:21:11.000000', NULL, 1),
(5570869, 806729, 98171, '<td valign="top">I have favorited and wish-listed this. Its just positively beautiful. I like the unique perspective, the lighting, the B&amp;W.... too bad Im not a member and I cant give you a 10.</td>', 'I have favorited and wish-listed this. Its just positively beautiful. I like the unique perspective, the lighting, the B&W.... too bad Im not a member and I cant give you a 10.', '2009-07-13 13:23:26.000000', NULL, 1),
(5570873, 806179, 98171, '<td valign="top">I think I would prefer it without the border. But this photo is very beautiful. The color is so ambient (is that a word??). I would love to have a print of this (minus the border).</td>', 'I think I would prefer it without the border. But this photo is very beautiful. The color is so ambient (is that a word??). I would love to have a print of this (minus the border).', '2009-07-13 13:25:46.000000', NULL, 1),
(5570884, 806174, 95579, '<td valign="top">Would have prefered the lefthand flower to also be in focus</td>', 'Would have prefered the lefthand flower to also be in focus', '2009-07-13 13:33:45.000000', NULL, 1),
(5570886, 806881, 95579, '<td valign="top">really pretty. Like the gradient in the water</td>', 'really pretty. Like the gradient in the water', '2009-07-13 13:34:23.000000', NULL, 1),
(5570889, 805954, 95579, '<td valign="top">Amazing colours. Background really adds to the vibrancy of the flower. Border works nicely</td>', 'Amazing colours. Background really adds to the vibrancy of the flower. Border works nicely', '2009-07-13 13:36:09.000000', NULL, 1),
(5570899, 805898, 98171, '<td valign="top">lol @ "not artwork". Im interested to see how you do this. Very mysterious, interesting photo.</td>', 'lol @ "not artwork". Im interested to see how you do this. Very mysterious, interesting photo.', '2009-07-13 13:42:41.000000', NULL, 1),
(5570903, 806719, 98171, '<td valign="top">I cant decide if i like the DOF or not. I think I do =) The pale pink against the black just pops, its gorgeous. I am a hater of the thick black borders, but it doesn''t really affect what I think about this photo. I guess that means it is not adding or detracting to the photo in any way.</td>', 'I cant decide if i like the DOF or not. I think I do =) The pale pink against the black just pops, its gorgeous. I am a hater of the thick black borders, but it doesn''t really affect what I think about this photo. I guess that means it is not adding or detracting to the photo in any way.', '2009-07-13 13:44:55.000000', NULL, 1),
(5570905, 806530, 49109, '<td valign="top">beautiful!nice DOF and well composed</td>', 'beautiful!nice DOF and well composed', '2009-07-13 13:45:05.000000', NULL, 1),
(5570907, 806777, 108564, '<td valign="top">Really pretty choice in Flower....I might have done a different composition and cropped a bit tighter.  Also, I find the petal on the left (the one coming toward the screen) to be blocking my view a bit...might have preferred a different angle.  Still, good exposure. Average for me.  5.</td>', 'Really pretty choice in Flower....I might have done a different composition and cropped a bit tighter.  Also, I find the petal on the left (the one coming toward the screen) to be blocking my view a bit...might have preferred a different angle.  Still, good exposure. Average for me.  5.', '2009-07-13 13:45:16.000000', NULL, 1),
(5570911, 806366, 98171, '<td valign="top">This is a great photo, I think this is a definite possibility to ribbon. So crisp, in focus, and the color just jumps out at you.</td>', 'This is a great photo, I think this is a definite possibility to ribbon. So crisp, in focus, and the color just jumps out at you.', '2009-07-13 13:45:51.000000', NULL, 1),
(5570912, 806900, 108564, '<td valign="top">I really love the choice in flower.....but the exposure is a bit dark for my taste.  That may have been intentional...not sure.  Good composition though.  I have to give a 4 because of the exposure though.</td>', 'I really love the choice in flower.....but the exposure is a bit dark for my taste.  That may have been intentional...not sure.  Good composition though.  I have to give a 4 because of the exposure though.', '2009-07-13 13:46:06.000000', NULL, 1),
(5570914, 805852, 108564, '<td valign="top">Those are really interesting flowers.  I would have cropped this tighter so all that space on the left is gone.  I think the focus is more on the bee than the flower.  I have to give it a 4.</td>', 'Those are really interesting flowers.  I would have cropped this tighter so all that space on the left is gone.  I think the focus is more on the bee than the flower.  I have to give it a 4.', '2009-07-13 13:47:00.000000', NULL, 1),
(5570916, 806627, 98171, '<td valign="top">I hate when people are way nitpicky about technicals, but in this case, it really affects how I feel about the photo: wish you had not centered the flower. The color contrast is very dramatic, makign it a really great photo. Just wish the flower was off center.</td>', 'I hate when people are way nitpicky about technicals, but in this case, it really affects how I feel about the photo: wish you had not centered the flower. The color contrast is very dramatic, makign it a really great photo. Just wish the flower was off center.', '2009-07-13 13:47:14.000000', NULL, 1),
(5570917, 806636, 108564, '<td valign="top">To me, the bug is the focus, not the flowers.  None of the flowers are in perfect focus, so it is hard to judge.  I give a 3 because of the subject.</td>', 'To me, the bug is the focus, not the flowers.  None of the flowers are in perfect focus, so it is hard to judge.  I give a 3 because of the subject.', '2009-07-13 13:47:59.000000', NULL, 1),
(5570919, 806295, 98171, '<td valign="top">On the page of thumbnails, my eye keeps getting drawn back to this photo. The use of white/gray is beautiful, and I love the perspective.</td>', 'On the page of thumbnails, my eye keeps getting drawn back to this photo. The use of white/gray is beautiful, and I love the perspective.', '2009-07-13 13:48:37.000000', NULL, 1),
(5570921, 806698, 108564, '<td valign="top">This makes me feel happy!!! Lovely use of shallow DOF and the water on the petals is lovely.  Great color and composition.  There is a bit of blown out yellow on the flower''s center. 8.</td>', 'This makes me feel happy!!! Lovely use of shallow DOF and the water on the petals is lovely.  Great color and composition.  There is a bit of blown out yellow on the flower''s center. 8.', '2009-07-13 13:49:14.000000', NULL, 1),
(5570924, 806865, 108564, '<td valign="top">I like what you were going for....but I think more DOF is in order.  The very center is a bit too dark for my liking....it is like a black hole which doesn''t do the rest of the flower any justice. 4.</td>', 'I like what you were going for....but I think more DOF is in order.  The very center is a bit too dark for my liking....it is like a black hole which doesn''t do the rest of the flower any justice. 4.', '2009-07-13 13:50:38.000000', NULL, 1),
(5570929, 805149, 108564, '<td valign="top">This feels over-processed to me.  Very nice lighting though.  I think you could have done less water drops. 4.</td>', 'This feels over-processed to me.  Very nice lighting though.  I think you could have done less water drops. 4.', '2009-07-13 13:51:20.000000', NULL, 1),
(5570932, 806591, 108564, '<td valign="top">YEEEEEEEEEEESSSSSS!!!!  This is fabulous, creative and awesome in the color and composition.  The DOF is perfect....everything about it is perfect. 10.</td>', 'YEEEEEEEEEEESSSSSS!!!!  This is fabulous, creative and awesome in the color and composition.  The DOF is perfect....everything about it is perfect. 10.', '2009-07-13 13:52:03.000000', NULL, 1),
(5570934, 806764, 108564, '<td valign="top">Very cute idea.  The flower has a bit too much shadow falling on the left....but this is very creative as a concept.  7.</td>', 'Very cute idea.  The flower has a bit too much shadow falling on the left....but this is very creative as a concept.  7.', '2009-07-13 13:52:42.000000', NULL, 1),
(5570936, 805180, 108564, '<td valign="top">Beautiful.....good idea just showing us the edge of the flower...good flower choice for that.  I love the color and the background.  Nice lighting too.  8.</td>', 'Beautiful.....good idea just showing us the edge of the flower...good flower choice for that.  I love the color and the background.  Nice lighting too.  8.', '2009-07-13 13:53:21.000000', NULL, 1),
(5570937, 805074, 108564, '<td valign="top">I love the color in this.  I''m not a huge fan of the subject...it just seems a bit messy to me.  But the light falling from the side is nice and I give you points for choosing an odd POV.  5.</td>', 'I love the color in this.  I''m not a huge fan of the subject...it just seems a bit messy to me.  But the light falling from the side is nice and I give you points for choosing an odd POV.  5.', '2009-07-13 13:54:27.000000', NULL, 1),
(5570940, 805902, 97073, '<td valign="top">Great colours here, the composition is very busy which is a little distracting but an overall good shot.</td>', 'Great colours here, the composition is very busy which is a little distracting but an overall good shot.', '2009-07-13 13:55:34.000000', NULL, 1),
(5570942, 806864, 97073, '<td valign="top">Nice, crisp and clear.</td>', 'Nice, crisp and clear.', '2009-07-13 13:55:45.000000', NULL, 1),
