(5571173, 806174, 108564, '<td valign="top">I don''t like how you cut off the vase...or the shadow hanging on the vase from the left flower.  5.</td>', 'I don''t like how you cut off the vase...or the shadow hanging on the vase from the left flower.  5.', '2009-07-13 15:27:48.000000', NULL, 1),
(5571174, 806808, 108564, '<td valign="top">Exposure on the flower is too dark.  I also would have used a reflector or something to throw some of that beautiful light on there. 4</td>', 'Exposure on the flower is too dark.  I also would have used a reflector or something to throw some of that beautiful light on there. 4', '2009-07-13 15:28:20.000000', NULL, 1),
