(5571188, 805314, 108564, '<td valign="top">Love the artsy, impressionist feel of this with the noise grain....nice colors.  Creative processing.  7.</td>', 'Love the artsy, impressionist feel of this with the noise grain....nice colors.  Creative processing.  7.', '2009-07-13 15:32:57.000000', NULL, 1),
