(5571208, 806709, 92577, '<td valign="top">clever idea well executed. My kind of composition too.</td>', 'clever idea well executed. My kind of composition too.', '2009-07-13 15:43:07.000000', NULL, 1),
(5571209, 806762, 43774, '<td valign="top">I don''t like the selective desaturation. And to make it worse, you missed some spots and it looks sloppy. In my opinion if you''re going to do selective desaturation, get it right or don''t do it at all. Sorry if that sounds harsh, but that''s how I feel.<br/> <br/>The flower is pretty, nice detail in the petals but the center looks oversaturated.</td>', 'I don''t like the selective desaturation. And to make it worse, you missed some spots and it looks sloppy. In my opinion if you''re going to do selective desaturation, get it right or don''t do it at all. Sorry if that sounds harsh, but that''s how I feel. The flower is pretty, nice detail in the petals but the center looks oversaturated.', '2009-07-13 15:43:07.000000', NULL, 1),
(5571210, 806830, 43774, '<td valign="top">Too faded looking for my tastes and I''d rather see the focus and detail on the flower and not the brown stems.</td>', 'Too faded looking for my tastes and I''d rather see the focus and detail on the flower and not the brown stems.', '2009-07-13 15:43:41.000000', NULL, 1),
