(5571510, 806625, 99506, '<td valign="top">Now this is nice. I love the way the crack in the wall seems to represent a rift between the two flowers as if they were two people who have argued or split which seems to be reflected in the title. Good work</td>', 'Now this is nice. I love the way the crack in the wall seems to represent a rift between the two flowers as if they were two people who have argued or split which seems to be reflected in the title. Good work', '2009-07-13 16:54:29.000000', NULL, 1),
(5571511, 806295, 99506, '<td valign="top">beautiful and different, very nice</td>', 'beautiful and different, very nice', '2009-07-13 16:55:15.000000', NULL, 1),
(5571513, 806610, 99506, '<td valign="top">very nice, very nice indeed</td>', 'very nice, very nice indeed', '2009-07-13 16:55:42.000000', NULL, 1),
(5571515, 806743, 52472, '<td valign="top">I really like this. It''s one of the few flower shots which tells a story beside just being aesthetic. Well done!</td>', 'I really like this. It''s one of the few flower shots which tells a story beside just being aesthetic. Well done!', '2009-07-13 16:56:10.000000', NULL, 1),
(5571518, 806767, 52472, '<td valign="top">It welcomes you into the buzzing world of insects. The right dose of impressionism works very well for me.</td>', 'It welcomes you into the buzzing world of insects. The right dose of impressionism works very well for me.', '2009-07-13 16:59:17.000000', NULL, 1),
(5571522, 806628, 99506, '<td valign="top">lovely use of shallow DOF in conjunction with the little girl to give a real nostalgic summer feel</td>', 'lovely use of shallow DOF in conjunction with the little girl to give a real nostalgic summer feel', '2009-07-13 17:01:16.000000', NULL, 1),
(5571524, 806594, 52472, '<td valign="top">The very dramatic composition loses a bit the essence of the flowers.</td>', 'The very dramatic composition loses a bit the essence of the flowers.', '2009-07-13 17:03:49.000000', NULL, 1),
