(5571530, 806758, 54446, '<td valign="top">Wonderful.  Love the lighting and the shadow play.  My favorite in this challenge.  10</td>', 'Wonderful.  Love the lighting and the shadow play.  My favorite in this challenge.  10', '2009-07-13 17:06:41.000000', NULL, 1),
(5571534, 806719, 69368, '<td valign="top">love the dramatic expression. Nice interpretation of the challenge<br/>... coming back for bumping up!</td>', 'love the dramatic expression. Nice interpretation of the challenge... coming back for bumping up!', '2009-07-13 17:07:09.000000', NULL, 1),
(5571535, 805365, 101707, '<td valign="top">What an incredible and disturbing image. I fear this won''t do well at the final score but it is my favorite image. well done.</td>', 'What an incredible and disturbing image. I fear this won''t do well at the final score but it is my favorite image. well done.', '2009-07-13 17:08:17.000000', NULL, 1),
(5571542, 806864, 52472, '<td valign="top">It''s nice to be shown the other side of things from time to time. It''s also a dangerous way to go, but you mastered it with a fantastic composition! 10</td>', 'It''s nice to be shown the other side of things from time to time. It''s also a dangerous way to go, but you mastered it with a fantastic composition! 10', '2009-07-13 17:13:49.000000', NULL, 1),
(5571544, 806535, 99506, '<td valign="top">This is simply beautiful, the composition and processing really work well.</td>', 'This is simply beautiful, the composition and processing really work well.', '2009-07-13 17:14:34.000000', NULL, 1),
