(5571547, 806552, 99506, '<td valign="top">Nice composition but there seems to be a lot of noise in the background</td>', 'Nice composition but there seems to be a lot of noise in the background', '2009-07-13 17:18:56.000000', NULL, 1),
(5571549, 805954, 52472, '<td valign="top">Maybe a bit too much void on the left. Very original, like a beauty from another planet. Fantastic colours. Macro at its best!</td>', 'Maybe a bit too much void on the left. Very original, like a beauty from another planet. Fantastic colours. Macro at its best!', '2009-07-13 17:22:27.000000', NULL, 1),
(5571558, 805522, 99506, '<td valign="top">The peony is a lovely flower and your shot highlights its beauty.<br/>Th exposure in this shot is spot on, no noticable blown out areas at all, great work</td>', 'The peony is a lovely flower and your shot highlights its beauty.Th exposure in this shot is spot on, no noticable blown out areas at all, great work', '2009-07-13 17:27:34.000000', NULL, 1),
