(5571574, 806392, 99506, '<td valign="top">ooooo very water colour.. nice</td>', 'ooooo very water colour.. nice', '2009-07-13 17:39:03.000000', NULL, 1),
(5571575, 806895, 99506, '<td valign="top">You have used shallow DOF here to great affect in my opinion, beautiful image that seems to capture the moment.</td>', 'You have used shallow DOF here to great affect in my opinion, beautiful image that seems to capture the moment.', '2009-07-13 17:40:11.000000', NULL, 1),
(5571576, 806193, 99506, '<td valign="top">i quite like high key shots although I''m guessing most here won''t.</td>', 'i quite like high key shots although I''m guessing most here won''t.', '2009-07-13 17:41:34.000000', NULL, 1),
(5571577, 806726, 52472, '<td valign="top">Hi there, teammate. I already know that you are a bit disappointed with your score, so I''ll try to guess why it does not please the crowds. Firstly, it sounds a bit stupid but I think the flower coming down from the upper right corner looks a bit unnatural and set up. Parallel and maybe slightly wrapped in the paper might have worked better.<br/>Secondly, the composition, the focus and the lighting are all on the paper. I do absolutely love the 3D-impression you get from the crinkles and shadows. Unfortunately, the perfection in one place draws the attention away from the flower. I doubt it''s very comforting, but I''m sure that in a "letter" challenge it would have scored very well.<br/> <br/>Obviously I cannot vote, but I would have given you a 6</td>', 'Hi there, teammate. I already know that you are a bit disappointed with your score, so I''ll try to guess why it does not please the crowds. Firstly, it sounds a bit stupid but I think the flower coming down from the upper right corner looks a bit unnatural and set up. Parallel and maybe slightly wrapped in the paper might have worked better.Secondly, the composition, the focus and the lighting are all on the paper. I do absolutely love the 3D-impression you get from the crinkles and shadows. Unfortunately, the perfection in one place draws the attention away from the flower. I doubt it''s very comforting, but I''m sure that in a "letter" challenge it would have scored very well. Obviously I cannot vote, but I would have given you a 6', '2009-07-13 17:41:46.000000', NULL, 1),
(5571578, 806870, 99506, '<td valign="top">wow this looks more like a shot from an edoscope that a pic of a flower. Very interesting.</td>', 'wow this looks more like a shot from an edoscope that a pic of a flower. Very interesting.', '2009-07-13 17:42:17.000000', NULL, 1),
