(5571581, 806738, 99506, '<td valign="top">I love this composition here and the beautiful paper type look to the dry petals. Great execution</td>', 'I love this composition here and the beautiful paper type look to the dry petals. Great execution', '2009-07-13 17:44:47.000000', NULL, 1),
(5571583, 806504, 99506, '<td valign="top">another great high key shot</td>', 'another great high key shot', '2009-07-13 17:45:27.000000', NULL, 1),
