(5571669, 806904, 52500, '<td valign="top">Wow.  Amazing.  This image just stopped me in my tracks and I stared at it for a couple of minutes.  I really, really like it.  A 10 and a fav for sure.  I love the way it breaks itself into 4 quadrants.</td>', 'Wow.  Amazing.  This image just stopped me in my tracks and I stared at it for a couple of minutes.  I really, really like it.  A 10 and a fav for sure.  I love the way it breaks itself into 4 quadrants.', '2009-07-13 18:54:34.000000', NULL, 1),
(5571672, 806286, 33361, '<td valign="top">super fly!!!</td>', 'super fly!!!', '2009-07-13 18:54:58.000000', NULL, 1),
(5571701, 806895, 45475, '<td valign="top">Oh my word, this is a stunning photograph. Leaving the out of focus children in the comp was an excellent decision too. Adds to the feeling of building excitement and anticipation, which is starkly at odds with the ''bored'' demeanor of the young lass there. Great control of light, great moment in time to have captured for the bride and groom.</td>', 'Oh my word, this is a stunning photograph. Leaving the out of focus children in the comp was an excellent decision too. Adds to the feeling of building excitement and anticipation, which is starkly at odds with the ''bored'' demeanor of the young lass there. Great control of light, great moment in time to have captured for the bride and groom.', '2009-07-13 19:15:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5571714, 806392, 77196, '<td valign="top">Different effect, but you stopped at the flower &amp; leaves. So, you have a nice smooth photographic background and a rather intense filter. To me, the looks clash and are not pleasing. <br/>Even with the texture, the dead leaves are still very visible. <br/>Nice lighting.</td>', 'Different effect, but you stopped at the flower & leaves. So, you have a nice smooth photographic background and a rather intense filter. To me, the looks clash and are not pleasing. Even with the texture, the dead leaves are still very visible. Nice lighting.', '2009-07-13 19:33:47.000000', NULL, 1),
(5571715, 805365, 77196, '<td valign="top">The bright grass and overlit daisies detract a lot from the mood of this shot.</td>', 'The bright grass and overlit daisies detract a lot from the mood of this shot.', '2009-07-13 19:35:32.000000', NULL, 1),
(5571739, 806628, 12076, '<td valign="top">Excellent, excellent shot.  I love the glow around the petals.  I''m always trying for the good, creative shots of my kids.  This is so inspiring.</td>', 'Excellent, excellent shot.  I love the glow around the petals.  I''m always trying for the good, creative shots of my kids.  This is so inspiring.', '2009-07-13 19:55:28.000000', NULL, 1),
(5571743, 806895, 12076, '<td valign="top">Different, good, and highly rated by me.  I suppose the boy in the right corner is a bit of a distraction...  Still and 8.</td>', 'Different, good, and highly rated by me.  I suppose the boy in the right corner is a bit of a distraction...  Still and 8.', '2009-07-13 19:56:59.000000', NULL, 1),
(5571746, 806403, 12076, '<td valign="top">This photo has the look of someone familiar.  I can''t place it...<br/> <br/>Lensbaby, I assume, and put to very good use.  Great take on the challenge, great tones, great title (but that doesn''t count for anything).  Currently a 9.  The next time I look at it I may have to bump it up a notch.</td>', 'This photo has the look of someone familiar.  I can''t place it... Lensbaby, I assume, and put to very good use.  Great take on the challenge, great tones, great title (but that doesn''t count for anything).  Currently a 9.  The next time I look at it I may have to bump it up a notch.', '2009-07-13 19:59:58.000000', NULL, 1),
(5571747, 805365, 12076, '<td valign="top">Different, funny, a bit too much contrast for my taste (particularly in the daisies).</td>', 'Different, funny, a bit too much contrast for my taste (particularly in the daisies).', '2009-07-13 20:01:16.000000', NULL, 1),
(5571748, 806858, 12076, '<td valign="top">One of my favorites.  Great soft tones...</td>', 'One of my favorites.  Great soft tones...', '2009-07-13 20:02:04.000000', NULL, 1),
(5571753, 806193, 12076, '<td valign="top">So, how is your score looking so far?  My guess is this one''s not for your day-today DPC crowd.  But I love it, which may not be saying much.  So subtle and soft.  Nice work.</td>', 'So, how is your score looking so far?  My guess is this one''s not for your day-today DPC crowd.  But I love it, which may not be saying much.  So subtle and soft.  Nice work.', '2009-07-13 20:04:26.000000', NULL, 1),
(5571754, 805999, 12076, '<td valign="top">Not overly unique, but absolutely stunning in execution.  I mean, it''s <i>perfect</i>!  8</td>', 'Not overly unique, but absolutely stunning in execution.  I mean, it''s perfect!  8', '2009-07-13 20:05:53.000000', NULL, 1),
(5571757, 806752, 12076, '<td valign="top">Excellent.  Reminds me of my teenage daughter...  soft, gentle, pretty...  but some sharp barbs that I hope fall off someday soon.</td>', 'Excellent.  Reminds me of my teenage daughter...  soft, gentle, pretty...  but some sharp barbs that I hope fall off someday soon.', '2009-07-13 20:07:36.000000', NULL, 1),
(5571759, 805297, 12076, '<td valign="top">Very well executed.  The two droplets remind me of eyes, so that''s a bit of a distraction, IMHO.  7</td>', 'Very well executed.  The two droplets remind me of eyes, so that''s a bit of a distraction, IMHO.  7', '2009-07-13 20:08:43.000000', NULL, 1),
(5571760, 806616, 12076, '<td valign="top">7 when I first voted.  Now an 8.  Great shot, color, dof. Oh heck...  should be a 9.</td>', '7 when I first voted.  Now an 8.  Great shot, color, dof. Oh heck...  should be a 9.', '2009-07-13 20:09:50.000000', NULL, 1),
(5571763, 805530, 12076, '<td valign="top">Very good macro.  The detail in the ant''s head and surrounding petal is incredible.  Seems to be more about the ant than the flower.  7</td>', 'Very good macro.  The detail in the ant''s head and surrounding petal is incredible.  Seems to be more about the ant than the flower.  7', '2009-07-13 20:11:41.000000', NULL, 1),
