INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5572609, 806614, 75849, '<td valign="top">Reminds me of Ursula''s work :-) Very nice.</td>', 'Reminds me of Ursula''s work :-) Very nice.', '2009-07-14 10:43:34.000000', NULL, 1),
(5572838, 806512, 106109, '<td valign="top">I''m not sure the emphasis is on the flowers, but I sure like this shot. Lighting and color are spot on. Beautiful.</td>', 'I''m not sure the emphasis is on the flowers, but I sure like this shot. Lighting and color are spot on. Beautiful.', '2009-07-14 14:14:33.000000', NULL, 1),
(5573058, 806193, 98647, '<td valign="top">That''s different, but you may have pushed the processing a little too far. Just a little more detail would have made this better for me.</td>', 'That''s different, but you may have pushed the processing a little too far. Just a little more detail would have made this better for me.', '2009-07-14 16:55:21.000000', NULL, 1),
(5573059, 806809, 7889, '<td valign="top">I really like this a lot, its different. I would like to see this cropped to show just the roses. Good luck</td>', 'I really like this a lot, its different. I would like to see this cropped to show just the roses. Good luck', '2009-07-14 16:55:44.000000', NULL, 1),
(5573066, 806698, 7889, '<td valign="top">These are one of my favourite flowers and this is an excellent photo, well done</td>', 'These are one of my favourite flowers and this is an excellent photo, well done', '2009-07-14 16:57:06.000000', NULL, 1),
(5573077, 806532, 7889, '<td valign="top">Different and I like this, only the background spoils it a little for me.</td>', 'Different and I like this, only the background spoils it a little for me.', '2009-07-14 16:58:34.000000', NULL, 1),
(5573078, 805570, 98647, '<td valign="top">The leaf going across the middle of the flower is distracting. I would''ve removed it before taking the shot.</td>', 'The leaf going across the middle of the flower is distracting. I would''ve removed it before taking the shot.', '2009-07-14 16:58:36.000000', NULL, 1),
(5573082, 805898, 7889, '<td valign="top">Brave ! This is why I still stay on this site - to see someone do something so different from the usual. You may well get hammered but please dont change the way YOU want to photograph. Kudos.</td>', 'Brave ! This is why I still stay on this site - to see someone do something so different from the usual. You may well get hammered but please dont change the way YOU want to photograph. Kudos.', '2009-07-14 17:00:36.000000', NULL, 1),
(5573083, 806707, 30049, '<td valign="top">While this is interesting, I think the "drop" is WAY too big and loses any credibility to being an actual waterdrop.  Otherwise you have nice detail and clarity.  Good luck in the challenge.</td>', 'While this is interesting, I think the "drop" is WAY too big and loses any credibility to being an actual waterdrop.  Otherwise you have nice detail and clarity.  Good luck in the challenge.', '2009-07-14 17:00:48.000000', NULL, 1),
(5573085, 806870, 98647, '<td valign="top">I wonder what this looks like in colour. This version is mostly the same shade of grey which makes it rather dull.</td>', 'I wonder what this looks like in colour. This version is mostly the same shade of grey which makes it rather dull.', '2009-07-14 17:01:34.000000', NULL, 1),
(5573086, 806295, 7889, '<td valign="top">Just wonderful ! I think this is outstanding. Best of luck.</td>', 'Just wonderful ! I think this is outstanding. Best of luck.', '2009-07-14 17:02:18.000000', NULL, 1),
(5573087, 806744, 7889, '<td valign="top">This would look even better than it does if you had taken it off centre. Still a lovely photograph.</td>', 'This would look even better than it does if you had taken it off centre. Still a lovely photograph.', '2009-07-14 17:03:09.000000', NULL, 1),
(5573088, 805297, 30049, '<td valign="top">I think you''d have been better off without the large drop on the right and just gone with one.   Other than that, and this type of imagery being somewhat cliche-ish now at DPC, it''s a fun photo and the bg color is great.  Good luck!</td>', 'I think you''d have been better off without the large drop on the right and just gone with one.   Other than that, and this type of imagery being somewhat cliche-ish now at DPC, it''s a fun photo and the bg color is great.  Good luck!', '2009-07-14 17:03:14.000000', NULL, 1),
(5573090, 806801, 7889, '<td valign="top">This would make an excellent print, I can see it hanging on a wall to light up a dark corner. Well done.</td>', 'This would make an excellent print, I can see it hanging on a wall to light up a dark corner. Well done.', '2009-07-14 17:03:51.000000', NULL, 1),
(5573091, 806371, 30049, '<td valign="top">Looks like you just found an excuse to put a mostly naked person in the challenge, eh?  Sorry, but flowers don''t seem to be the main subject here.  In any case, best of luck to you.</td>', 'Looks like you just found an excuse to put a mostly naked person in the challenge, eh?  Sorry, but flowers don''t seem to be the main subject here.  In any case, best of luck to you.', '2009-07-14 17:04:16.000000', NULL, 1),
(5573094, 806675, 30049, '<td valign="top">You have a nice dried flower arrangement working here.  Why''d you have to toss in a naked lady?  Makes the subject of this photo more than the flowers, although I imagine your views are skyrocketing.  :-)  Good luck.</td>', 'You have a nice dried flower arrangement working here.  Why''d you have to toss in a naked lady?  Makes the subject of this photo more than the flowers, although I imagine your views are skyrocketing.  :-)  Good luck.', '2009-07-14 17:06:05.000000', NULL, 1),
(5573096, 806893, 7889, '<td valign="top">Beautiful shot, which I expect to do well. The colour is so vibrant.</td>', 'Beautiful shot, which I expect to do well. The colour is so vibrant.', '2009-07-14 17:06:38.000000', NULL, 1),
(5573101, 806881, 7889, '<td valign="top">There are a lot of great photos in this challenge and this is up there with the best, well done and good luck.</td>', 'There are a lot of great photos in this challenge and this is up there with the best, well done and good luck.', '2009-07-14 17:07:36.000000', NULL, 1),
(5573112, 806591, 65319, '<td valign="top">Wow...I love this one...10!</td>', 'Wow...I love this one...10!', '2009-07-14 17:11:57.000000', NULL, 1),
(5573129, 805010, 65234, '<td valign="top">Cheery composition; the softness works well with the raindrops.</td>', 'Cheery composition; the softness works well with the raindrops.', '2009-07-14 17:22:55.000000', NULL, 1),
