(5575418, 806445, 102019, '<td valign="top">Good for her!  lol...</td>', 'Good for her!  lol...', '2009-07-15 18:39:03.000000', NULL, 1),
(5575425, 806403, 102019, '<td valign="top">Okay, first, it''s not a flower (yes, yes, I see the apron.  What''s your point?).  Second, it''s boring.  Third, the framing is static.  And fourth...  hmm, well there isn''t a fourth.  But I just don''t like it.</td>', 'Okay, first, it''s not a flower (yes, yes, I see the apron.  What''s your point?).  Second, it''s boring.  Third, the framing is static.  And fourth...  hmm, well there isn''t a fourth.  But I just don''t like it.', '2009-07-15 18:45:01.000000', NULL, 1),
