(5576704, 806551, 94815, '<td valign="top">Black bg works well.</td>', 'Black bg works well.', '2009-07-16 17:11:09.000000', NULL, 1),
(5576705, 806370, 94815, '<td valign="top">Good timing. :-)</td>', 'Good timing. :-)', '2009-07-16 17:11:38.000000', NULL, 1),
(5576706, 805901, 94815, '<td valign="top">Does it help? Good beiges.</td>', 'Does it help? Good beiges.', '2009-07-16 17:12:11.000000', NULL, 1),
(5576707, 806135, 94815, '<td valign="top">The water seems a distraction but nice detail.</td>', 'The water seems a distraction but nice detail.', '2009-07-16 17:12:50.000000', NULL, 1),
(5576708, 806744, 94815, '<td valign="top">Centered works here and bokeh all around makes it float.</td>', 'Centered works here and bokeh all around makes it float.', '2009-07-16 17:13:24.000000', NULL, 1),
(5576710, 805297, 94815, '<td valign="top">For impressively creative vision - 8.</td>', 'For impressively creative vision - 8.', '2009-07-16 17:14:11.000000', NULL, 1),
(5576711, 806870, 94815, '<td valign="top">Impressive visual effect as if being sucked into a hole.</td>', 'Impressive visual effect as if being sucked into a hole.', '2009-07-16 17:15:00.000000', NULL, 1),
(5576713, 805522, 94815, '<td valign="top">Impressive detail makes us more aware of the parts than the whole.</td>', 'Impressive detail makes us more aware of the parts than the whole.', '2009-07-16 17:16:16.000000', NULL, 1),
(5576824, 806758, 99263, '<td valign="top">Visually very pleasing shot. Lovely composition, great lighting and nice detail.</td>', 'Visually very pleasing shot. Lovely composition, great lighting and nice detail.', '2009-07-16 19:32:42.000000', NULL, 1),
(5576826, 806135, 99263, '<td valign="top">Simply stunning</td>', 'Simply stunning', '2009-07-16 19:33:15.000000', NULL, 1),
(5576888, 806043, 76598, '<td valign="top">The colors are pretty, but it has an abstractness to it that I am not sure of...can''t be sure it is a flower</td>', 'The colors are pretty, but it has an abstractness to it that I am not sure of...can''t be sure it is a flower', '2009-07-16 20:42:24.000000', NULL, 1),
(5576889, 806291, 76598, '<td valign="top">The Lilly gets lost in the background...a little closer and an angle that separated it from the background would be good</td>', 'The Lilly gets lost in the background...a little closer and an angle that separated it from the background would be good', '2009-07-16 20:43:37.000000', NULL, 1),
(5576890, 806892, 76598, '<td valign="top">spooky, an interesting take on the challenge</td>', 'spooky, an interesting take on the challenge', '2009-07-16 20:44:38.000000', NULL, 1),
(5576893, 805955, 76598, '<td valign="top">Butterfly Weed...of the milkweed family</td>', 'Butterfly Weed...of the milkweed family', '2009-07-16 20:45:08.000000', NULL, 1),
(5576900, 806904, 76598, '<td valign="top">Aesthetically there are some pleasing parts to this image, but all the white sort of bothers me.  my tendency is to score it very high or very low.... 6</td>', 'Aesthetically there are some pleasing parts to this image, but all the white sort of bothers me.  my tendency is to score it very high or very low.... 6', '2009-07-16 20:51:32.000000', NULL, 1),
(5576905, 806900, 76598, '<td valign="top">a little too dark</td>', 'a little too dark', '2009-07-16 20:53:51.000000', NULL, 1),
(5576910, 806392, 76598, '<td valign="top">ummm, not sure where to go with this, it is a little too blurred and uniform to really say "art", but I like the daring to move outside the norm.</td>', 'ummm, not sure where to go with this, it is a little too blurred and uniform to really say "art", but I like the daring to move outside the norm.', '2009-07-16 20:58:31.000000', NULL, 1),
(5577071, 806719, 89223, '<td valign="top">i love the color tones in this photo as well as the mood it put off to me.<br/>i feel like the blured part of the rose is a bit overwelming in the frame and it tends to catch my eye. lovely work either way nice job!</td>', 'i love the color tones in this photo as well as the mood it put off to me.i feel like the blured part of the rose is a bit overwelming in the frame and it tends to catch my eye. lovely work either way nice job!', '2009-07-16 23:23:51.000000', NULL, 1),
(5577130, 806719, 57447, '<td valign="top">Like it!</td>', 'Like it!', '2009-07-16 23:58:21.000000', NULL, 1),
(5577297, 806054, 99263, '<td valign="top">What a beauty</td>', 'What a beauty', '2009-07-17 05:44:34.000000', NULL, 1),
(5577298, 806611, 99263, '<td valign="top">Absolutely beautiful shot.</td>', 'Absolutely beautiful shot.', '2009-07-17 05:45:06.000000', NULL, 1),
(5577299, 806374, 99263, '<td valign="top">Stunning luminosity.</td>', 'Stunning luminosity.', '2009-07-17 05:45:42.000000', NULL, 1),
(5577300, 806809, 99263, '<td valign="top">Stunning bouquet of roses. That rose in the top left hand side really adds a nice touch. Did you paint it like that?</td>', 'Stunning bouquet of roses. That rose in the top left hand side really adds a nice touch. Did you paint it like that?', '2009-07-17 05:47:12.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5577301, 806622, 99263, '<td valign="top">A beauty.</td>', 'A beauty.', '2009-07-17 05:47:23.000000', NULL, 1),
(5577302, 805854, 99263, '<td valign="top">Stunning.</td>', 'Stunning.', '2009-07-17 05:47:45.000000', NULL, 1),
(5577303, 806369, 99263, '<td valign="top">Strikingly beautiful.</td>', 'Strikingly beautiful.', '2009-07-17 05:47:58.000000', NULL, 1),
(5577304, 806610, 99263, '<td valign="top">Lovely creamy color. Beautiful and unusual.</td>', 'Lovely creamy color. Beautiful and unusual.', '2009-07-17 05:48:48.000000', NULL, 1),
(5577305, 806748, 99263, '<td valign="top">Wonderful color,detail and texture. Like old parchment.</td>', 'Wonderful color,detail and texture. Like old parchment.', '2009-07-17 05:49:27.000000', NULL, 1),
(5577306, 806153, 99263, '<td valign="top">Lovely.</td>', 'Lovely.', '2009-07-17 05:49:37.000000', NULL, 1),
(5577307, 806539, 99263, '<td valign="top">Great.</td>', 'Great.', '2009-07-17 05:49:56.000000', NULL, 1),
(5577308, 805584, 99263, '<td valign="top">Great shot.</td>', 'Great shot.', '2009-07-17 05:50:26.000000', NULL, 1),
(5577309, 805751, 99263, '<td valign="top">Striking shot of this beautiful bouquet of flowers. Lovely detail.</td>', 'Striking shot of this beautiful bouquet of flowers. Lovely detail.', '2009-07-17 05:50:30.000000', NULL, 1),
(5577310, 806388, 99263, '<td valign="top">Striking and beautiful.</td>', 'Striking and beautiful.', '2009-07-17 05:50:33.000000', NULL, 1),
(5577311, 806371, 99263, '<td valign="top">Great lighting, processing and editing in this creative image.</td>', 'Great lighting, processing and editing in this creative image.', '2009-07-17 05:50:35.000000', NULL, 1),
(5577312, 806551, 99263, '<td valign="top">Simply beautiful.</td>', 'Simply beautiful.', '2009-07-17 05:50:49.000000', NULL, 1),
(5577314, 805522, 99263, '<td valign="top">Fantastic detail and lighting. Lovely image.</td>', 'Fantastic detail and lighting. Lovely image.', '2009-07-17 05:51:18.000000', NULL, 1),
(5577315, 806686, 99263, '<td valign="top">Nice idea and nice editing.</td>', 'Nice idea and nice editing.', '2009-07-17 05:51:51.000000', NULL, 1),
(5577316, 806585, 99263, '<td valign="top">Simple yet beautiful.</td>', 'Simple yet beautiful.', '2009-07-17 05:52:17.000000', NULL, 1),
(5577317, 806508, 99263, '<td valign="top">Wonderful shot.Great dof and lovely pastel like colors.</td>', 'Wonderful shot.Great dof and lovely pastel like colors.', '2009-07-17 05:53:08.000000', NULL, 1),
(5577318, 806237, 99263, '<td valign="top">Sheer beauty.</td>', 'Sheer beauty.', '2009-07-17 05:53:22.000000', NULL, 1),
(5577319, 806741, 99263, '<td valign="top">Lovely. Super detail and lighting.</td>', 'Lovely. Super detail and lighting.', '2009-07-17 05:54:03.000000', NULL, 1),
(5577320, 806172, 99263, '<td valign="top">Lovely vivid colors and great lighting. A beautiful image.</td>', 'Lovely vivid colors and great lighting. A beautiful image.', '2009-07-17 05:54:39.000000', NULL, 1),
(5577322, 806893, 99263, '<td valign="top">Stunning shot.</td>', 'Stunning shot.', '2009-07-17 05:54:53.000000', NULL, 1),
(5577440, 806731, 30049, '<td valign="top">Sharp, vibrant, and real.  Refreshing change of scenery from the many studio/staged photos.  While I gave this a 10 earlier (coming back around to comment) I wonder if this wouldn''t be a touch stronger presentation if you lost a bit of the top and left. ???  Anyway...best of luck to you in the challenge.</td>', 'Sharp, vibrant, and real.  Refreshing change of scenery from the many studio/staged photos.  While I gave this a 10 earlier (coming back around to comment) I wonder if this wouldn''t be a touch stronger presentation if you lost a bit of the top and left. ???  Anyway...best of luck to you in the challenge.', '2009-07-17 11:36:36.000000', NULL, 1),
(5577441, 806614, 30049, '<td valign="top">This is one of my favorite "natural" shots and I absolutely love the shallow DOF on the leading edge.  Well done!</td>', 'This is one of my favorite "natural" shots and I absolutely love the shallow DOF on the leading edge.  Well done!', '2009-07-17 11:37:14.000000', NULL, 1),
(5577443, 806838, 30049, '<td valign="top">This gets a top score from me (voted earlier...coming back around to comment) for creativity.  Very well executed shot and well seen.  Good luck!</td>', 'This gets a top score from me (voted earlier...coming back around to comment) for creativity.  Very well executed shot and well seen.  Good luck!', '2009-07-17 11:38:21.000000', NULL, 1),
(5577445, 806858, 30049, '<td valign="top">Nice comp, good choice for aperture setting to keep some bg detail, and great touch on the processing.  A top pick for me (voted earlier, coming back around to comment).  Good luck!</td>', 'Nice comp, good choice for aperture setting to keep some bg detail, and great touch on the processing.  A top pick for me (voted earlier, coming back around to comment).  Good luck!', '2009-07-17 11:40:17.000000', NULL, 1),
(5577448, 806290, 30049, '<td valign="top">I really like this.  One of my top picks (gave it a 10 earlier...coming back around for commenting).  Very creative take on the challenge.  I''m so glad you went this way rather than taking the easy studio/setup route.  A very refreshing entry.  Good luck in the challenge!</td>', 'I really like this.  One of my top picks (gave it a 10 earlier...coming back around for commenting).  Very creative take on the challenge.  I''m so glad you went this way rather than taking the easy studio/setup route.  A very refreshing entry.  Good luck in the challenge!', '2009-07-17 11:42:22.000000', NULL, 1),
(5577453, 806616, 30049, '<td valign="top">First I must say this is wonderfully processed!  I''m a sucker for the soft focus look and you nailed it.  Absolutely perfect exposure, nice dynamic comp - I can''t find one single thing to nitpik on!  I gave this a 10 during voting earlier and coming back around to comment.  After looking again I think I need to add this to my fav''s!  :-)  See you on the front page at rollover.  Congrats!</td>', 'First I must say this is wonderfully processed!  I''m a sucker for the soft focus look and you nailed it.  Absolutely perfect exposure, nice dynamic comp - I can''t find one single thing to nitpik on!  I gave this a 10 during voting earlier and coming back around to comment.  After looking again I think I need to add this to my fav''s!  :-)  See you on the front page at rollover.  Congrats!', '2009-07-17 11:45:46.000000', NULL, 1),
(5577454, 806724, 30049, '<td valign="top">Wonderful job with this still life.  Well balanced with nice use of lighting.  Good luck in the challenge.</td>', 'Wonderful job with this still life.  Well balanced with nice use of lighting.  Good luck in the challenge.', '2009-07-17 11:45:52.000000', NULL, 1),
(5577483, 806535, 101445, '<td valign="top">my favorite of the challenge</td>', 'my favorite of the challenge', '2009-07-17 12:24:05.000000', NULL, 1),
(5577487, 806724, 101445, '<td valign="top">one of my favorites of the challenge</td>', 'one of my favorites of the challenge', '2009-07-17 12:24:20.000000', NULL, 1),
(5577639, 806195, 103142, '<td valign="top">This stands out nicely from the rest (so far, but I think I''m most of the way through). I liked the dead flower, but I think this one is much more stunning!</td>', 'This stands out nicely from the rest (so far, but I think I''m most of the way through). I liked the dead flower, but I think this one is much more stunning!', '2009-07-17 15:06:37.000000', NULL, 1),
(5577640, 806745, 103142, '<td valign="top">not voting yet, but this is one of the few thumbnails that got me interested in looking right now.  It''s very nicely done! congrats!</td>', 'not voting yet, but this is one of the few thumbnails that got me interested in looking right now.  It''s very nicely done! congrats!', '2009-07-17 15:07:39.000000', NULL, 1),
(5577725, 806724, 68956, '<td valign="top">Beautifully set up and photographed, I would hope to see this high on the front page ;)</td>', 'Beautifully set up and photographed, I would hope to see this high on the front page ;)', '2009-07-17 16:56:13.000000', NULL, 1),
(5577726, 806135, 68956, '<td valign="top">You''ve captured so much beautiful detail:)</td>', 'You''ve captured so much beautiful detail:)', '2009-07-17 16:56:45.000000', NULL, 1),
(5577727, 806789, 67258, '<td valign="top">This photo doesn''t really work for me.  The very narrow depth of field has resulted in out of focus petals to the front of the flower, and these seem to act almost as a barrier.  My brain struggles to make sense of the jumble of petals presented.</td>', 'This photo doesn''t really work for me.  The very narrow depth of field has resulted in out of focus petals to the front of the flower, and these seem to act almost as a barrier.  My brain struggles to make sense of the jumble of petals presented.', '2009-07-17 16:57:52.000000', NULL, 1),
(5577732, 806814, 67258, '<td valign="top">A pretty flower, well exposed, good focus, good background, but the overall effect is badly damaged by the heavy black border - white would seem to be much more in keeping with the mood of the image.</td>', 'A pretty flower, well exposed, good focus, good background, but the overall effect is badly damaged by the heavy black border - white would seem to be much more in keeping with the mood of the image.', '2009-07-17 17:02:00.000000', NULL, 1),
(5577736, 806791, 67258, '<td valign="top">A straightforward approach with good focus and choice of DoF.  The light looks a little harsh for flower photographer and may have been softer earlier in the day.</td>', 'A straightforward approach with good focus and choice of DoF.  The light looks a little harsh for flower photographer and may have been softer earlier in the day.', '2009-07-17 17:08:53.000000', NULL, 1),
(5577737, 806771, 67258, '<td valign="top">A Paeony?  The flower shows well against the black background, although the light is a tad on the harsh side. The wide depth of field, allowing for the whole of the flower to be in focus makes for an interesting image.  I do though, find the bud in the foreground very distracting.</td>', 'A Paeony?  The flower shows well against the black background, although the light is a tad on the harsh side. The wide depth of field, allowing for the whole of the flower to be in focus makes for an interesting image.  I do though, find the bud in the foreground very distracting.', '2009-07-17 17:09:01.000000', NULL, 1),
(5577738, 806445, 67258, '<td valign="top">Aww, there will be someone else out there for you! An interesting oob idea, and a refreshing change.  I am not particularly keen on the harsh light, which has resulted in a heavy shadow over the left arm, which does rather spoil your carefully composed symmetry.</td>', 'Aww, there will be someone else out there for you! An interesting oob idea, and a refreshing change.  I am not particularly keen on the harsh light, which has resulted in a heavy shadow over the left arm, which does rather spoil your carefully composed symmetry.', '2009-07-17 17:09:04.000000', NULL, 1),
(5577739, 805570, 67258, '<td valign="top">The focus appears to be on the petals, and I do feel that in this image the critical sharpness needed to be on the bee.  The colours are good and strong, befitting your subject.  I do though, find my eyes drawn to the right and the vertical green line - a stake, or a blade of grass perhaps?</td>', 'The focus appears to be on the petals, and I do feel that in this image the critical sharpness needed to be on the bee.  The colours are good and strong, befitting your subject.  I do though, find my eyes drawn to the right and the vertical green line - a stake, or a blade of grass perhaps?', '2009-07-17 17:09:10.000000', NULL, 1),
(5577741, 806856, 67258, '<td valign="top">A strange medley of objects to accompany the sun-flower.  I usually like the use of shallow depth of field, but here it has given the effect of a fake background.</td>', 'A strange medley of objects to accompany the sun-flower.  I usually like the use of shallow depth of field, but here it has given the effect of a fake background.', '2009-07-17 17:09:20.000000', NULL, 1),
(5577742, 806691, 67258, '<td valign="top">I am not entirely convinced the relatively cluttered ''context giving'' background works with the specific composition you have chosen.  That said, it is a pretty flower and you display good detail in its petals and centre.</td>', 'I am not entirely convinced the relatively cluttered ''context giving'' background works with the specific composition you have chosen.  That said, it is a pretty flower and you display good detail in its petals and centre.', '2009-07-17 17:09:23.000000', NULL, 1),
(5577746, 806880, 67258, '<td valign="top">The green finger nails on the scarecrow definitely scare me, even if it doesn''t scare the crows! I like the idea behind the photo, but am not sure the composition and focal point entirely work for me.</td>', 'The green finger nails on the scarecrow definitely scare me, even if it doesn''t scare the crows! I like the idea behind the photo, but am not sure the composition and focal point entirely work for me.', '2009-07-17 17:09:37.000000', NULL, 1),
(5577747, 806769, 67258, '<td valign="top">A pretty bouquet, with strong vibrant colours, and a softness that suits the subject.  The composition does seem just a little too haphazard for my tastes, and I find myself trying to look beyond the bottom of the picture.</td>', 'A pretty bouquet, with strong vibrant colours, and a softness that suits the subject.  The composition does seem just a little too haphazard for my tastes, and I find myself trying to look beyond the bottom of the picture.', '2009-07-17 17:09:42.000000', NULL, 1),
(5577748, 806409, 67258, '<td valign="top">You have caught the featheriness of the Astilbe well.  The light does appear a little harsh - I wonder if a photo taken in the earliest morning light would work better.</td>', 'You have caught the featheriness of the Astilbe well.  The light does appear a little harsh - I wonder if a photo taken in the earliest morning light would work better.', '2009-07-17 17:09:51.000000', NULL, 1),
(5577749, 806820, 67258, '<td valign="top">The flower shows nicely against the dark background, and your method of B&amp;W conversion works well for the subject.  I am less convinced by the composition, which to my eyes doesn''t really compliment the subject, and appears somewhat dull.</td>', 'The flower shows nicely against the dark background, and your method of B&W conversion works well for the subject.  I am less convinced by the composition, which to my eyes doesn''t really compliment the subject, and appears somewhat dull.', '2009-07-17 17:09:54.000000', NULL, 1),
(5577751, 806841, 67258, '<td valign="top">An interesting choice of presentation with the heavy vignette, and it has certainly made for a dramatic image.  The simple border is effective.</td>', 'An interesting choice of presentation with the heavy vignette, and it has certainly made for a dramatic image.  The simple border is effective.', '2009-07-17 17:15:50.000000', NULL, 1),
(5577752, 806881, 67258, '<td valign="top">A simple and minimal approach that works well, although I might prefer the flower to be smaller within the frame, to accentuate it''s fragility.</td>', 'A simple and minimal approach that works well, although I might prefer the flower to be smaller within the frame, to accentuate it''s fragility.', '2009-07-17 17:15:53.000000', NULL, 1),
(5577754, 806748, 67258, '<td valign="top">I love the colours of this poppy - no idea if they are natural or manipulated in PP, but if they are real, I want one for my garden!  You have allowed the papery texture and graininess to show through well, and your choice of dof allows the whole of the flower head to be in sharp focus, which works well for this study.  I am somewhat unsure about the  black back-ground - because there is no stem or foliage in frame it does give a rather stark, de-capitated look.</td>', 'I love the colours of this poppy - no idea if they are natural or manipulated in PP, but if they are real, I want one for my garden!  You have allowed the papery texture and graininess to show through well, and your choice of dof allows the whole of the flower head to be in sharp focus, which works well for this study.  I am somewhat unsure about the  black back-ground - because there is no stem or foliage in frame it does give a rather stark, de-capitated look.', '2009-07-17 17:16:02.000000', NULL, 1),
(5577756, 806821, 67258, '<td valign="top">The black background makes for a very clean image and shows the flowers off well, and focus and lighting are sound.  I find myself wishing that the two uppermost petals weren''t clipped by the top of the frame.</td>', 'The black background makes for a very clean image and shows the flowers off well, and focus and lighting are sound.  I find myself wishing that the two uppermost petals weren''t clipped by the top of the frame.', '2009-07-17 17:16:04.000000', NULL, 1),
(5577761, 806414, 67258, '<td valign="top">The sgle flower amongst the buds is effective.  I rather wish the stamen was also in focus, but acknowledge controlling dof to that level requires an enormous amount of skill.</td>', 'The sgle flower amongst the buds is effective.  I rather wish the stamen was also in focus, but acknowledge controlling dof to that level requires an enormous amount of skill.', '2009-07-17 17:19:14.000000', NULL, 1),
(5577762, 806754, 67258, '<td valign="top">What strange and intriguing stamens!  Your choice of DoF works well.  Surprisingly, the insect appears incidental to the image, and I suspect it would work just as well without it; indeed, the colour of the insect does rather clash with the vibrant green of the flower parts!</td>', 'What strange and intriguing stamens!  Your choice of DoF works well.  Surprisingly, the insect appears incidental to the image, and I suspect it would work just as well without it; indeed, the colour of the insect does rather clash with the vibrant green of the flower parts!', '2009-07-17 17:19:22.000000', NULL, 1),
(5577764, 806779, 67258, '<td valign="top">The flower is a good subject for your study; I particularly like the way the muted colours are echoed in the oof background.  I am not particularly keen on your choice of crop - the flower seems constrained and cramped by your framing.</td>', 'The flower is a good subject for your study; I particularly like the way the muted colours are echoed in the oof background.  I am not particularly keen on your choice of crop - the flower seems constrained and cramped by your framing.', '2009-07-17 17:19:27.000000', NULL, 1),
(5577767, 805074, 67258, '<td valign="top">An interesting photo with an apt title.  Whilst not making it into my personal top 10, I do admire your take on the challenge, and the flower (cow parsley?) is photographed well.</td>', 'An interesting photo with an apt title.  Whilst not making it into my personal top 10, I do admire your take on the challenge, and the flower (cow parsley?) is photographed well.', '2009-07-17 17:21:03.000000', NULL, 1),
(5577771, 806871, 67258, '<td valign="top">A simple and unpretentious photo of a flower clearly in situ in it''s garden environment.  The perspective works well, showing the flower to full advantage, and the background has been thrown pleasingly out of focus whilst still providing enough detail to give context.  I rather wish the teracotta and grey horizontal stripes weren''t present, and that the background foliage extended to these areas, but despite that, a strong entry.</td>', 'A simple and unpretentious photo of a flower clearly in situ in it''s garden environment.  The perspective works well, showing the flower to full advantage, and the background has been thrown pleasingly out of focus whilst still providing enough detail to give context.  I rather wish the teracotta and grey horizontal stripes weren''t present, and that the background foliage extended to these areas, but despite that, a strong entry.', '2009-07-17 17:21:18.000000', NULL, 1),
(5577772, 806835, 67258, '<td valign="top">Well photographed with good colour rendition.  I am not entirely convinced by the inclusion of the whole oof flower in the background - for me, despite the symmetry, it somehow unbalances the composition.  Nonthe less, a strong entry.</td>', 'Well photographed with good colour rendition.  I am not entirely convinced by the inclusion of the whole oof flower in the background - for me, despite the symmetry, it somehow unbalances the composition.  Nonthe less, a strong entry.', '2009-07-17 17:21:27.000000', NULL, 1),
(5577773, 806770, 67258, '<td valign="top">i really like the composition here, and the simplicity of the image.  the muted colours of the background provide a pleasing foil to the flower head, and there is just the right amount of separation between the two.</td>', 'i really like the composition here, and the simplicity of the image.  the muted colours of the background provide a pleasing foil to the flower head, and there is just the right amount of separation between the two.', '2009-07-17 17:21:29.000000', NULL, 1),
(5577780, 806404, 67258, '<td valign="top">Very pretty, interest provided by the perfectly placed water drops. Critical focus just right, and lovely colour rendition.  A gorgeous photo with bags of impact.</td>', 'Very pretty, interest provided by the perfectly placed water drops. Critical focus just right, and lovely colour rendition.  A gorgeous photo with bags of impact.', '2009-07-17 17:25:45.000000', NULL, 1),
(5577781, 806838, 67258, '<td valign="top">I really like this, the discord between the sharp manmade barrier and the soft, gentle naturalness of the daisy and grasses.  The rain reinforces to the overall feel, making the fence and barbed wire seem even more dark and forboding, yet bringing out the vibrancy of the yellows and greens.  A thoroughly pleasing study.</td>', 'I really like this, the discord between the sharp manmade barrier and the soft, gentle naturalness of the daisy and grasses.  The rain reinforces to the overall feel, making the fence and barbed wire seem even more dark and forboding, yet bringing out the vibrancy of the yellows and greens.  A thoroughly pleasing study.', '2009-07-17 17:25:57.000000', NULL, 1),
(5577785, 806120, 67258, '<td valign="top">Excellent depth of field for the subject, vibrant but natural colours, pleasing background bokeh.  Not so keen on the oof orange flower(?) that is to the right, I do find it rather distracting - it may have been possible to reduce the saturation of it a little to disguise it somewhat.</td>', 'Excellent depth of field for the subject, vibrant but natural colours, pleasing background bokeh.  Not so keen on the oof orange flower(?) that is to the right, I do find it rather distracting - it may have been possible to reduce the saturation of it a little to disguise it somewhat.', '2009-07-17 17:27:10.000000', NULL, 1),
(5577787, 805297, 67258, '<td valign="top">Done many a-time before, but by gum, you have done it well!</td>', 'Done many a-time before, but by gum, you have done it well!', '2009-07-17 17:28:04.000000', NULL, 1),
(5577788, 806827, 67258, '<td valign="top">A very strong image, beautifully presented.  Excellent work.</td>', 'A very strong image, beautifully presented.  Excellent work.', '2009-07-17 17:28:17.000000', NULL, 1),
(5577834, 805999, 39850, '<td valign="top">9 - Oooo.  Very good.</td>', '9 - Oooo.  Very good.', '2009-07-17 18:12:51.000000', NULL, 1),
(5577844, 806748, 39850, '<td valign="top">8 - This is very ''full on'' but I think it would be excellent as a feature print, framed appropriately.  I really like the detail and texture you''ve captured.  I only noticed the bug on the second look - ''if only'' he/she were in focus too, or maybe not... who knows - works well regardless.  I find it a little odd, as mentioned above, that this borders on a spriteish kind of image, without a stem showing, etc - but again, I think it would have a place in ''prints''... if that makes sense.</td>', '8 - This is very ''full on'' but I think it would be excellent as a feature print, framed appropriately.  I really like the detail and texture you''ve captured.  I only noticed the bug on the second look - ''if only'' he/she were in focus too, or maybe not... who knows - works well regardless.  I find it a little odd, as mentioned above, that this borders on a spriteish kind of image, without a stem showing, etc - but again, I think it would have a place in ''prints''... if that makes sense.', '2009-07-17 18:22:57.000000', NULL, 1),
(5577852, 806594, 39850, '<td valign="top">8 - Beautiful image and nice composition and processing.  I like that you''ve ''illustrated'' how a flower garden is a balanced and composed ''frame'' in and of itself (if that makes sense).  Of course, your title, which of course is personal, adds another dimension to this too (good one) - as somebody planned, created &amp; composed this ''scene'' - and worked with ''nature'' in harmony to bring it to full potential - which it certainly looks like it is.  I think you captured ''all that'' well.  I even like the OOF fore as well, ok maybe a little more included at the bottom for a little more palette balance, but minor.</td>', '8 - Beautiful image and nice composition and processing.  I like that you''ve ''illustrated'' how a flower garden is a balanced and composed ''frame'' in and of itself (if that makes sense).  Of course, your title, which of course is personal, adds another dimension to this too (good one) - as somebody planned, created & composed this ''scene'' - and worked with ''nature'' in harmony to bring it to full potential - which it certainly looks like it is.  I think you captured ''all that'' well.  I even like the OOF fore as well, ok maybe a little more included at the bottom for a little more palette balance, but minor.', '2009-07-17 18:31:08.000000', NULL, 1),
(5577853, 805297, 39850, '<td valign="top">8 - Nice simplicity and colors.</td>', '8 - Nice simplicity and colors.', '2009-07-17 18:32:22.000000', NULL, 1),
(5577856, 806370, 39850, '<td valign="top">8 - Excellent and perfect title.  Really like that this is a pumpkin flower.  Really like the colors and composition, but do wish for a fraction more space above/to the right of the ''do''.</td>', '8 - Excellent and perfect title.  Really like that this is a pumpkin flower.  Really like the colors and composition, but do wish for a fraction more space above/to the right of the ''do''.', '2009-07-17 18:33:44.000000', NULL, 1),
(5577858, 806819, 39850, '<td valign="top">8 - Really like the sheerness of this and the colors and processing too.  Good detail and such subtle OOF fore.</td>', '8 - Really like the sheerness of this and the colors and processing too.  Good detail and such subtle OOF fore.', '2009-07-17 18:34:41.000000', NULL, 1),
(5577859, 806172, 39850, '<td valign="top">8 - Well titled.</td>', '8 - Well titled.', '2009-07-17 18:34:48.000000', NULL, 1),
(5577860, 806861, 39850, '<td valign="top">8 - Very nice choice of flowers and good study and detail in them.  Tones are very nice.  Like the tall framing, but still - well undecided on a fraction more room above with this image - but hey, not my call anyway..</td>', '8 - Very nice choice of flowers and good study and detail in them.  Tones are very nice.  Like the tall framing, but still - well undecided on a fraction more room above with this image - but hey, not my call anyway..', '2009-07-17 18:36:12.000000', NULL, 1),
(5577861, 806530, 39850, '<td valign="top">8 - Very nice, nice choice of flowers too, look like an alium(?) - would like to have seen a little more height above the flowers.</td>', '8 - Very nice, nice choice of flowers too, look like an alium(?) - would like to have seen a little more height above the flowers.', '2009-07-17 18:36:25.000000', NULL, 1),
(5577863, 806614, 39850, '<td valign="top">8 - Nice soft image but yet bold colors.  Like the barely discernible soft grain - wonder about it even more visible, but maybe another image.  Slightly more refined crop, maybe - but that''s just my opinion.</td>', '8 - Nice soft image but yet bold colors.  Like the barely discernible soft grain - wonder about it even more visible, but maybe another image.  Slightly more refined crop, maybe - but that''s just my opinion.', '2009-07-17 18:38:37.000000', NULL, 1),
(5577867, 806755, 39850, '<td valign="top">7 - Nice capture.</td>', '7 - Nice capture.', '2009-07-17 18:43:02.000000', NULL, 1),
(5577872, 805966, 39850, '<td valign="top">7 - Nice study - especially like the perfectly pressed/preserved stamens, anthers &amp; (I think) stigma.</td>', '7 - Nice study - especially like the perfectly pressed/preserved stamens, anthers & (I think) stigma.', '2009-07-17 18:44:22.000000', NULL, 1),
(5577873, 806816, 39850, '<td valign="top">7 - ''Ah Lotus''.  Beautiful colors and really like the detail in the center.</td>', '7 - ''Ah Lotus''.  Beautiful colors and really like the detail in the center.', '2009-07-17 18:44:54.000000', NULL, 1),
(5577877, 806904, 39850, '<td valign="top">7 - I like this - also like how you have shown the beauty of these flowers when they have fallen.</td>', '7 - I like this - also like how you have shown the beauty of these flowers when they have fallen.', '2009-07-17 18:47:30.000000', NULL, 1),
(5577878, 806724, 39850, '<td valign="top">7 - Nicely done - excellent composition.</td>', '7 - Nicely done - excellent composition.', '2009-07-17 18:47:49.000000', NULL, 1),
(5577879, 806610, 39850, '<td valign="top">7 - Beautiful shape/curve study.</td>', '7 - Beautiful shape/curve study.', '2009-07-17 18:48:07.000000', NULL, 1),
(5577881, 806742, 39850, '<td valign="top">6 - Like this, especially how you''ve shown how the flowers transform and paint a landscape, which your processing has enhanced.  Just wish they were a little more dominant overall in the image.</td>', '6 - Like this, especially how you''ve shown how the flowers transform and paint a landscape, which your processing has enhanced.  Just wish they were a little more dominant overall in the image.', '2009-07-17 18:49:17.000000', NULL, 1),
(5577909, 805906, 3087, '<td valign="top">Lovely sharp detail of the pollen against the softer blurred area.</td>', 'Lovely sharp detail of the pollen against the softer blurred area.', '2009-07-17 19:14:19.000000', NULL, 1),
(5577911, 806817, 3087, '<td valign="top">Wow, fabulous high contrast really makes those pollen-laden stamens stand out. Almost like fire. Striking!</td>', 'Wow, fabulous high contrast really makes those pollen-laden stamens stand out. Almost like fire. Striking!', '2009-07-17 19:15:16.000000', NULL, 1),
(5577912, 805874, 3087, '<td valign="top">A beautiful piece of art, the black background and careful lighting work nicely.</td>', 'A beautiful piece of art, the black background and careful lighting work nicely.', '2009-07-17 19:15:42.000000', NULL, 1),
(5577914, 806539, 3087, '<td valign="top">Lovely clarity of detail. Lighting seems a touch too harsh on some of the lower petals, draws my focus there unnaturally. But a lovely image and interesting to go sepia.</td>', 'Lovely clarity of detail. Lighting seems a touch too harsh on some of the lower petals, draws my focus there unnaturally. But a lovely image and interesting to go sepia.', '2009-07-17 19:17:02.000000', NULL, 1),
(5577915, 806628, 3087, '<td valign="top">Not a fan of the soft focus effect but a charming image indeed.</td>', 'Not a fan of the soft focus effect but a charming image indeed.', '2009-07-17 19:17:27.000000', NULL, 1),
(5577916, 806610, 3087, '<td valign="top">Wow, super structural, abstract, incredible shapes, what an ode to the architectural magnificence of nature!</td>', 'Wow, super structural, abstract, incredible shapes, what an ode to the architectural magnificence of nature!', '2009-07-17 19:17:57.000000', NULL, 1),
(5577917, 806724, 3087, '<td valign="top">Timeless, classic, beautifully executed. The soft and low lighting, allowing for some shadows to form, really works very well. Love it!</td>', 'Timeless, classic, beautifully executed. The soft and low lighting, allowing for some shadows to form, really works very well. Love it!', '2009-07-17 19:18:41.000000', NULL, 1),
(5577918, 806733, 3087, '<td valign="top">Nice use of lighting and gradiated background. Works well.</td>', 'Nice use of lighting and gradiated background. Works well.', '2009-07-17 19:19:25.000000', NULL, 1),
(5577920, 806616, 3087, '<td valign="top">Sweet and timeless, very classic. Composition excellent - less is more. Lovely.</td>', 'Sweet and timeless, very classic. Composition excellent - less is more. Lovely.', '2009-07-17 19:19:51.000000', NULL, 1),
(5577998, 806886, 78371, '<td valign="top">I like the cool color palette and the shallow dof to this photo.</td>', 'I like the cool color palette and the shallow dof to this photo.', '2009-07-17 21:02:49.000000', NULL, 1),
(5578000, 806392, 78371, '<td valign="top">The filter does not do anything for this photo at all.  It is a shame because it looks like that you have some nice lavender petals there.</td>', 'The filter does not do anything for this photo at all.  It is a shame because it looks like that you have some nice lavender petals there.', '2009-07-17 21:04:36.000000', NULL, 1),
(5578160, 806392, 16106, '<td valign="top">It is hard to see the flower because the editing is so heavy handed. Putting back some detail through a desaturated layer set to multiply might have given you the feeling you wanted with more sense of whatever detail there was here that drew you to shoot this image.</td>', 'It is hard to see the flower because the editing is so heavy handed. Putting back some detail through a desaturated layer set to multiply might have given you the feeling you wanted with more sense of whatever detail there was here that drew you to shoot this image.', '2009-07-18 01:20:32.000000', NULL, 1),
(5578306, 806025, 65234, '<td valign="top">Nice color and I like the soft shadows it casts.  Perspective is not especially unique but still a fine shot.</td>', 'Nice color and I like the soft shadows it casts.  Perspective is not especially unique but still a fine shot.', '2009-07-18 09:36:04.000000', NULL, 1),
(5578310, 806135, 65234, '<td valign="top">There''s a lot going on in the center of that flower!  Interesting subject and well captured.  Crop feels a little off to me; think I might like more room on the top and right or an even distance from the edge of the frame left/right/top.</td>', 'There''s a lot going on in the center of that flower!  Interesting subject and well captured.  Crop feels a little off to me; think I might like more room on the top and right or an even distance from the edge of the frame left/right/top.', '2009-07-18 09:38:23.000000', NULL, 1),
(5578313, 806280, 65234, '<td valign="top">Nice light and the flowers stand out beautifully with the desat of the foliage.  A bit of color fringing going on with the edges of the flower in back so I might try some touch up to eliminate it.</td>', 'Nice light and the flowers stand out beautifully with the desat of the foliage.  A bit of color fringing going on with the edges of the flower in back so I might try some touch up to eliminate it.', '2009-07-18 09:41:17.000000', NULL, 1),
(5578314, 806819, 65234, '<td valign="top">I saw one of these the other day; quite impressive.  Like your DOF and light.  Not scoring based on title but I wonder if it would suit the image better if it were flipped so the flower was rising out of the bottom of the image?</td>', 'I saw one of these the other day; quite impressive.  Like your DOF and light.  Not scoring based on title but I wonder if it would suit the image better if it were flipped so the flower was rising out of the bottom of the image?', '2009-07-18 09:44:04.000000', NULL, 1),
(5578415, 806104, 67258, '<td valign="top">An interesting soft focus image, which gives an over-worldly, perhaps under-water, feel.  The water drops are clearly dew drops, and the flower looks as though it is slowly unfurling its petals as the sun comes up.  <br/>edit - I initially gave this a 7, and over the last few days it has crept up and up, and you have ended with a  10 from me - a photo that i liked from the start and that grew with repeated viewings.</td>', 'An interesting soft focus image, which gives an over-worldly, perhaps under-water, feel.  The water drops are clearly dew drops, and the flower looks as though it is slowly unfurling its petals as the sun comes up.  edit - I initially gave this a 7, and over the last few days it has crept up and up, and you have ended with a  10 from me - a photo that i liked from the start and that grew with repeated viewings.', '2009-07-18 12:16:46.000000', NULL, 1),
(5578416, 806616, 67258, '<td valign="top">Beautifully subtle and so evocative of those summer days that probably never were - my idyll. a 10 from me.</td>', 'Beautifully subtle and so evocative of those summer days that probably never were - my idyll. a 10 from me.', '2009-07-18 12:17:48.000000', NULL, 1),
(5578417, 806817, 67258, '<td valign="top">This just like a view into the inferno - incredibly well done.</td>', 'This just like a view into the inferno - incredibly well done.', '2009-07-18 12:18:26.000000', NULL, 1),
(5578418, 806739, 67258, '<td valign="top">Superb use of complimentary colours.</td>', 'Superb use of complimentary colours.', '2009-07-18 12:18:50.000000', NULL, 1),
(5578419, 806813, 67258, '<td valign="top">This somehow makes me think of a baby in the womb - absolutely love it.</td>', 'This somehow makes me think of a baby in the womb - absolutely love it.', '2009-07-18 12:19:18.000000', NULL, 1),
(5578459, 806748, 78371, '<td valign="top">This is a really good photo.  The subtle tones of the purple textual petals really interacts well with the yellow stamens?...well the center part of the flower.  I hope that this photo scores high.</td>', 'This is a really good photo.  The subtle tones of the purple textual petals really interacts well with the yellow stamens?...well the center part of the flower.  I hope that this photo scores high.', '2009-07-18 13:21:31.000000', NULL, 1),
(5578465, 806295, 78371, '<td valign="top">beautiful... the composition is wonderful.  I like the combination of the basket-like texture of the pistil(?) and the softness of the flower petals.</td>', 'beautiful... the composition is wonderful.  I like the combination of the basket-like texture of the pistil(?) and the softness of the flower petals.', '2009-07-18 13:29:52.000000', NULL, 1),
(5578472, 806211, 78371, '<td valign="top">I think that the title is quite a good fit for this photograph.  I must say it certainly adds depth, though I liked this photo before I got the literary reference. I like the analogous color scheme and the abstract tones in the background.</td>', 'I think that the title is quite a good fit for this photograph.  I must say it certainly adds depth, though I liked this photo before I got the literary reference. I like the analogous color scheme and the abstract tones in the background.', '2009-07-18 13:39:58.000000', NULL, 1),
(5578495, 806760, 67238, '<td valign="top">i love the composition, HDR?</td>', 'i love the composition, HDR?', '2009-07-18 14:20:53.000000', NULL, 1),
(5578600, 806682, 78371, '<td valign="top">The blue is just so neon that I am looking more at the negative space than the actual flowers. The composition is good and I think that the flowers themselves are very interesting to look at. I especially like the dots at the bottom of the petals.</td>', 'The blue is just so neon that I am looking more at the negative space than the actual flowers. The composition is good and I think that the flowers themselves are very interesting to look at. I especially like the dots at the bottom of the petals.', '2009-07-18 18:47:35.000000', NULL, 1),
(5578611, 806882, 78371, '<td valign="top">Well this is certainly a lot of negative space, a bit too much for me.  Also, the plant is too far back in the frame, the details are sort of getting lost.</td>', 'Well this is certainly a lot of negative space, a bit too much for me.  Also, the plant is too far back in the frame, the details are sort of getting lost.', '2009-07-18 19:01:25.000000', NULL, 1),
(5578617, 806810, 78371, '<td valign="top">This is such an interesting flower. I wish there was more of it to see and maybe less of the busy background.  Saying that, the texture and colors of the the flower is great.</td>', 'This is such an interesting flower. I wish there was more of it to see and maybe less of the busy background.  Saying that, the texture and colors of the the flower is great.', '2009-07-18 19:08:12.000000', NULL, 1),
(5578622, 806868, 31664, '<td valign="top">I love the use of the light in this shot,  great composition</td>', 'I love the use of the light in this shot,  great composition', '2009-07-18 19:15:55.000000', NULL, 1),
(5578699, 806368, 78371, '<td valign="top">It seems that this might be a bit over-sharpened and yet it is not really in focus either.  I think though that the flower petals do make an interesting star shaped.  Also, I do like the addition of the flower''s leaves.</td>', 'It seems that this might be a bit over-sharpened and yet it is not really in focus either.  I think though that the flower petals do make an interesting star shaped.  Also, I do like the addition of the flower''s leaves.', '2009-07-18 21:31:41.000000', NULL, 1),
