(5579769, 806895, 67697, '<td valign="top">This is a very cute scene.  I think the boy smiling at you really makes the photo.</td>', 'This is a very cute scene.  I think the boy smiling at you really makes the photo.', '2009-07-20 00:51:24.000000', NULL, 1),
(5579771, 806807, 105792, '<td valign="top">Beautiful!!</td>', 'Beautiful!!', '2009-07-20 00:53:15.000000', NULL, 1),
