INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5580320, 806193, 81530, '<td valign="top">Everything a flower should be; delicate, soft, subtle. Lovely photo.</td>', 'Everything a flower should be; delicate, soft, subtle. Lovely photo.', '2009-07-20 10:39:46.000000', NULL, 0),
(5580321, 806403, 61651, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by pekesty:</b></div><hr/><i> It''s okay to not like a photo, and it''s okay to say why.  But why is it acceptable to be a complete ass about it?<br/> <br/>I''m sure if Rachel ever takes a photograph for the small minded, it''ll be a hit with kivgaen!<br/> <br/> </i></td></tr></table> <br/> <br/>What he said... it''s not the sentiment that''s objectionable, it''s how it was delivered.<br/> <br/>As for the conceptual nature of the shot, the more I look at it the more it makes me think of a further subtext, possibly intended, possibly not - the choice of focus placement and how it aligns with a certain area of the body, combined with a title that makes us wonder what constitutes a "good" wife.  Is is only domesticity that''s implied here by the apron, or something else?</td>', 'Originally posted by pekesty: It''s okay to not like a photo, and it''s okay to say why.  But why is it acceptable to be a complete ass about it? I''m sure if Rachel ever takes a photograph for the small minded, it''ll be a hit with kivgaen!    What he said... it''s not the sentiment that''s objectionable, it''s how it was delivered. As for the conceptual nature of the shot, the more I look at it the more it makes me think of a further subtext, possibly intended, possibly not - the choice of focus placement and how it aligns with a certain area of the body, combined with a title that makes us wonder what constitutes a "good" wife.  Is is only domesticity that''s implied here by the apron, or something else?', '2009-07-20 10:41:24.000000', NULL, 0),
