(5581440, 806689, 28742, '<td valign="top">Love the colors &amp; textures, Deb. Congrats on well deserved top ten!</td>', 'Love the colors & textures, Deb. Congrats on well deserved top ten!', '2009-07-21 07:19:50.000000', NULL, 0),
(5581442, 806719, 28742, '<td valign="top">Looks like it was quite the competitive challenge to find this gem so far down the list. I think maybe the border hurt it a bit. A great image nonetheless.</td>', 'Looks like it was quite the competitive challenge to find this gem so far down the list. I think maybe the border hurt it a bit. A great image nonetheless.', '2009-07-21 07:21:12.000000', NULL, 0),
