(5581547, 806768, 51597, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by annig:</b></div><hr/><i> pretty flower and composition, very muted presentation adds to the dramatic feel..odd the petals seem ragged on the edges! </i></td></tr></table> <br/> <br/>The edges of gloxinias are like that...</td>', 'Originally posted by annig: pretty flower and composition, very muted presentation adds to the dramatic feel..odd the petals seem ragged on the edges!   The edges of gloxinias are like that...', '2009-07-21 10:26:46.000000', NULL, 0),
(5581580, 806370, 50695, '<td valign="top">You got top twenty with a zucchini. You rock! Gorgeous shot.</td>', 'You got top twenty with a zucchini. You rock! Gorgeous shot.', '2009-07-21 11:05:16.000000', NULL, 0),
(5581591, 806689, 51269, '<td valign="top">I agree with Peter''s comment- the title &amp; how it so fits the image is a winning combo--also it''s a sweet one- that little Panasonic does a great job, but you were the artist !!!</td>', 'I agree with Peter''s comment- the title & how it so fits the image is a winning combo--also it''s a sweet one- that little Panasonic does a great job, but you were the artist !!!', '2009-07-21 11:20:58.000000', NULL, 0),
(5581620, 806870, 61961, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Saker:</b></div><hr/><i> I have sold four 11x14 prints on a metallic paper to people not involved with DP. Thank you for your comments and your votes and I am so appreciative to live in a country where we all have the right to our opinions.</i></td></tr></table> <br/>Good for you!  Fine shot; always good to remember that DPC is not the real world! :-)</td>', 'Originally posted by Saker: I have sold four 11x14 prints on a metallic paper to people not involved with DP. Thank you for your comments and your votes and I am so appreciative to live in a country where we all have the right to our opinions. Good for you!  Fine shot; always good to remember that DPC is not the real world! :-)', '2009-07-21 12:09:03.000000', NULL, 0),
(5581635, 806414, 14593, '<td valign="top">Shot with the LX3--not at all surprised!  nice photo</td>', 'Shot with the LX3--not at all surprised!  nice photo', '2009-07-21 12:34:43.000000', NULL, 0),
