(5581801, 805999, 107730, '<td valign="top">Not only is this my favourite flower, but if I had voted, you would have got a 10 from me for sure.  Great shot!  Love it!  Well done</td>', 'Not only is this my favourite flower, but if I had voted, you would have got a 10 from me for sure.  Great shot!  Love it!  Well done', '2009-07-21 16:35:10.000000', NULL, 0),
(5581864, 806724, 64929, '<td valign="top">One of the BEST Still Lifes I''ve ever seen on this site!!  Congrats!</td>', 'One of the BEST Still Lifes I''ve ever seen on this site!!  Congrats!', '2009-07-21 17:28:23.000000', NULL, 0),
(5581943, 806369, 40484, '<td valign="top">After viewing your outtakes, I think you made the right choice with this one. The light is just right to bring out all the lovely detail in this.</td>', 'After viewing your outtakes, I think you made the right choice with this one. The light is just right to bring out all the lovely detail in this.', '2009-07-21 19:21:07.000000', NULL, 0),
